#include <vector>
#include <algorithm>
#include <cstring>

using namespace std;

class Solution {
    int memo[500][500][4][2][2];
    int n, m;
    int dr[4] = {1, 1, -1, -1};
    int dc[4] = {1, -1, -1, 1};

    int dfs(const vector<vector<int>>& grid, int r, int c, int d, int turned, int targetIdx) {
        if (memo[r][c][d][turned][targetIdx] != -1) {
            return memo[r][c][d][turned][targetIdx];
        }
        int target = (targetIdx == 0) ? 2 : 0;
        int nextIdx = 1 - targetIdx;
        int res = 0;

        int nr = r + dr[d];
        int nc = c + dc[d];
        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == target) {
            res = max(res, 1 + dfs(grid, nr, nc, d, turned, nextIdx));
        }

        if (!turned) {
            int nd = (d + 1) % 4;
            int tr = r + dr[nd];
            int tc = c + dc[nd];
            if (tr >= 0 && tr < n && tc >= 0 && tc < m && grid[tr][tc] == target) {
                res = max(res, 1 + dfs(grid, tr, tc, nd, 1, nextIdx));
            }
        }

        return memo[r][c][d][turned][targetIdx] = res;
    }

public:
    int lenOfVDiagonal(vector<vector<int>>& grid) {
        n = grid.size();
        m = grid[0].size();
        memset(memo, -1, sizeof(memo));

        int ans = 0;
        bool hasOne = false;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 1) {
                    hasOne = true;
                    for (int d = 0; d < 4; d++) {
                        ans = max(ans, 1 + dfs(grid, r, c, d, 0, 0));
                    }
                }
            }
        }
        return hasOne ? ans : 0;
    }
};

class Solution {
    private int[][][][][] memo;
    private int n, m;
    private final int[] dr = {1, 1, -1, -1};
    private final int[] dc = {1, -1, -1, 1};

    private int dfs(int[][] grid, int r, int c, int d, int turned, int targetIdx) {
        if (memo[r][c][d][turned][targetIdx] != 0) {
            return memo[r][c][d][turned][targetIdx] - 1;
        }
        int target = (targetIdx == 0) ? 2 : 0;
        int nextIdx = 1 - targetIdx;
        int res = 0;

        int nr = r + dr[d];
        int nc = c + dc[d];
        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == target) {
            res = Math.max(res, 1 + dfs(grid, nr, nc, d, turned, nextIdx));
        }

        if (turned == 0) {
            int nd = (d + 1) % 4;
            int tr = r + dr[nd];
            int tc = c + dc[nd];
            if (tr >= 0 && tr < n && tc >= 0 && tc < m && grid[tr][tc] == target) {
                res = Math.max(res, 1 + dfs(grid, tr, tc, nd, 1, nextIdx));
            }
        }

        memo[r][c][d][turned][targetIdx] = res + 1;
        return res;
    }

    public int lenOfVDiagonal(int[][] grid) {
        n = grid.length;
        m = grid[0].length;
        memo = new int[n][m][4][2][2];

        int ans = 0;
        boolean hasOne = false;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 1) {
                    hasOne = true;
                    for (int d = 0; d < 4; d++) {
                        ans = Math.max(ans, 1 + dfs(grid, r, c, d, 0, 0));
                    }
                }
            }
        }
        return hasOne ? ans : 0;
    }
}

/**
 * @param {number[][]} grid
 * @return {number}
