var lenOfVDiagonal = function(grid) {
    const n = grid.length;
    const m = grid[0].length;
    const dr = [1, 1, -1, -1];
    const dc = [1, -1, -1, 1];
    const memo = new Map();

    function dfs(r, c, d, turned, target) {
        const key = `${r},${c},${d},${turned},${target}`;
        if (memo.has(key)) return memo.get(key);

        let res = 0;
        const nr = r + dr[d];
        const nc = c + dc[d];
        const nextTarget = target === 2 ? 0 : 2;

        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] === target) {
            res = Math.max(res, 1 + dfs(nr, nc, d, turned, nextTarget));
        }

        if (!turned) {
            const nd = (d + 1) % 4;
            const tr = r + dr[nd];
            const tc = c + dc[nd];
            if (tr >= 0 && tr < n && tc >= 0 && tc < m && grid[tr][tc] === target) {
                res = Math.max(res, 1 + dfs(tr, tc, nd, 1, nextTarget));
            }
        }

        memo.set(key, res);
        return res;
    }

    let ans = 0;
    let hasOne = false;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < m; c++) {
            if (grid[r][c] === 1) {
                hasOne = true;
                for (let d = 0; d < 4; d++) {
                    ans = Math.max(ans, 1 + dfs(r, c, d, 0, 2));
                }
            }
        }
    }
    return hasOne ? ans : 0;
};
